import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
import { agentApi } from '@/api/index';
export default {
  name: 'AgentCommand',
  data() {
    return {
      loading: false,
      commandLoading: false,
      historyLoading: false,
      agentListLoading: false,
      dialogVisible: false,
      showKey: false,
      currentPage: 1,
      pageSize: 10,
      total: 0,
      agentList: [],
      commandHistory: [],
      selectedCommand: null,
      commandForm: {
        agent_id: '',
        type: 'shell',
        content: '',
        timeout: 30
      },
      commandRules: {
        agent_id: [{
          required: true,
          message: '请选择Agent',
          trigger: 'change'
        }],
        type: [{
          required: true,
          message: '请选择命令类型',
          trigger: 'change'
        }],
        content: [{
          required: true,
          message: '请输入命令内容',
          trigger: 'blur'
        }],
        timeout: [{
          required: true,
          message: '请设置超时时间',
          trigger: 'change'
        }]
      },
      historyFilter: {
        agent_id: '',
        status: '',
        search: '',
        date_range: []
      },
      pickerOptions: {
        shortcuts: [{
          text: '最近一周',
          onClick(picker) {
            const end = new Date();
            const start = new Date();
            start.setTime(start.getTime() - 3600 * 1000 * 24 * 7);
            picker.$emit('pick', [start, end]);
          }
        }, {
          text: '最近一个月',
          onClick(picker) {
            const end = new Date();
            const start = new Date();
            start.setTime(start.getTime() - 3600 * 1000 * 24 * 30);
            picker.$emit('pick', [start, end]);
          }
        }, {
          text: '最近三个月',
          onClick(picker) {
            const end = new Date();
            const start = new Date();
            start.setTime(start.getTime() - 3600 * 1000 * 24 * 90);
            picker.$emit('pick', [start, end]);
          }
        }]
      },
      batchMode: false,
      templateDialogVisible: false,
      activeTemplateCategory: 'system',
      systemTemplates: [],
      fileTemplates: [],
      networkTemplates: []
    };
  },
  created() {
    this.fetchAgentList();
    this.fetchCommandHistory();
    this.initCommandTemplates();
    this.processQueryParams();
  },
  methods: {
    // 处理查询参数
    processQueryParams() {
      const {
        id
      } = this.$route.query;
      if (id) {
        this.commandForm.agent_id = id;
      }
    },
    // Agent列表相关方法
    async fetchAgentList() {
      this.agentListLoading = true;
      try {
        const response = await agentApi.getAgentList();
        if (response && response.code === 200) {
          // 处理返回的数据结构，将每个agent对象转换为列表项
          const agentData = response.data || {};
          this.agentList = Object.entries(agentData).map(([key, agent]) => ({
            id: agent.agent_uuid,
            // 使用agent_uuid作为id
            hostname: agent.hostname,
            // 使用hostname作为显示名称
            ip: agent.ip_addresses ? agent.ip_addresses[0] : '',
            // 使用第一个IP地址
            os: agent.os,
            // 操作系统信息
            status: agent.connected ? 'online' : 'offline' // 连接状态
          }));
        }
      } catch (error) {
        this.$message.error('获取Agent列表失败：' + error.message);
      } finally {
        this.agentListLoading = false;
      }
    },
    handleAgentSelectVisibleChange(visible) {
      if (visible) {
        this.fetchAgentList();
      }
    },
    getOsIcon(os) {
      if (!os) return 'el-icon-monitor';
      const osLower = os.toLowerCase();
      if (osLower.includes('windows')) return 'el-icon-platform-eleme';
      if (osLower.includes('linux')) return 'el-icon-platform-eleme';
      if (osLower.includes('darwin')) return 'el-icon-apple';
      return 'el-icon-monitor';
    },
    // 初始化命令模板
    initCommandTemplates() {
      // 初始化内置的命令模板
      this.systemTemplates = [{
        id: 1,
        name: '系统信息',
        description: '获取基础系统信息',
        type: 'shell',
        content: 'uname -a && cat /etc/os-release'
      }, {
        id: 2,
        name: '磁盘空间',
        description: '查看磁盘空间使用情况',
        type: 'shell',
        content: 'df -h'
      }, {
        id: 3,
        name: '内存信息',
        description: '查看内存使用情况',
        type: 'shell',
        content: 'free -m'
      }, {
        id: 4,
        name: 'CPU信息',
        description: '查看CPU信息',
        type: 'shell',
        content: 'cat /proc/cpuinfo'
      }, {
        id: 5,
        name: '进程列表',
        description: '查看占用资源最多的进程',
        type: 'shell',
        content: 'ps aux --sort=-%cpu | head -10'
      }];
      this.fileTemplates = [{
        id: 6,
        name: '列出目录',
        description: '列出指定目录内容',
        type: 'shell',
        content: 'ls -la /path/to/directory'
      }, {
        id: 7,
        name: '查找文件',
        description: '根据名称查找文件',
        type: 'shell',
        content: 'find / -name "filename" -type f'
      }, {
        id: 8,
        name: '最近修改',
        description: '列出最近修改的文件',
        type: 'shell',
        content: 'find / -type f -mtime -1 | grep -v "/proc/" | grep -v "/sys/" | head -20'
      }];
      this.networkTemplates = [{
        id: 9,
        name: '网络连接',
        description: '查看网络连接状态',
        type: 'shell',
        content: 'netstat -tuln'
      }, {
        id: 10,
        name: 'Ping测试',
        description: '测试与目标主机的连接',
        type: 'shell',
        content: 'ping -c 4 google.com'
      }, {
        id: 11,
        name: 'IP配置',
        description: '查看IP配置信息',
        type: 'shell',
        content: 'ip addr show'
      }, {
        id: 12,
        name: '路由表',
        description: '查看路由表',
        type: 'shell',
        content: 'ip route'
      }];
    },
    useTemplate(template) {
      this.commandForm.type = template.type || 'shell';
      this.commandForm.content = template.content;
      this.templateDialogVisible = false;
    },
    // 命令执行相关方法
    async executeCommand() {
      try {
        await this.$refs.commandForm.validate();
        this.commandLoading = true;
        if (this.batchMode && Array.isArray(this.commandForm.agent_id) && this.commandForm.agent_id.length > 0) {
          // 批量执行命令
          const results = [];
          let successCount = 0;
          let failCount = 0;
          for (const agentId of this.commandForm.agent_id) {
            try {
              const commandData = {
                agent_id: agentId,
                type: this.commandForm.type,
                content: this.commandForm.content,
                timeout: this.commandForm.timeout
              };
              const response = await agentApi.executeCommand(commandData);
              if (response && response.code === 200) {
                successCount++;
                results.push({
                  agentId,
                  commandId: response.data.command_id,
                  success: true
                });
              } else {
                failCount++;
                results.push({
                  agentId,
                  success: false,
                  error: response.msg || '命令执行失败'
                });
              }
            } catch (error) {
              failCount++;
              results.push({
                agentId,
                success: false,
                error: error.message || '命令执行出错'
              });
            }
          }
          if (successCount > 0) {
            this.$message.success(`成功发送命令至 ${successCount} 个Agent`);
          }
          if (failCount > 0) {
            this.$message.warning(`${failCount} 个Agent命令发送失败`);
          }

          // 更新命令历史
          setTimeout(() => {
            this.fetchCommandHistory();
          }, 1000);

          // 重置表单
          this.resetCommand();
        } else {
          // 单个Agent执行命令
          const commandData = {
            agent_id: this.batchMode ? this.commandForm.agent_id[0] : this.commandForm.agent_id,
            type: this.commandForm.type,
            content: this.commandForm.content,
            timeout: this.commandForm.timeout
          };
          const response = await agentApi.executeCommand(commandData);
          if (response && response.code === 200) {
            this.$message.success('命令已发送');

            // 获取命令ID
            const commandId = response.data.command_id;
            if (commandId) {
              // 立即获取并显示命令详情
              this.pollCommandResult(commandId);
            }

            // 更新命令历史
            setTimeout(() => {
              this.fetchCommandHistory();
            }, 1000);

            // 重置表单
            this.resetCommand();
          } else {
            this.$message.error(response.msg || '命令执行失败');
          }
        }
      } catch (error) {
        this.$message.error('命令执行失败：' + (error.message || '未知错误'));
      } finally {
        this.commandLoading = false;
      }
    },
    // 轮询命令结果
    async pollCommandResult(commandId, attempts = 0) {
      if (attempts > 20) {
        // 最多尝试20次，约1分钟
        this.$message.warning('命令执行时间较长，请在历史记录中查看结果');
        return;
      }
      try {
        const response = await agentApi.getCommandResult(commandId);
        if (response && response.code === 200) {
          const result = response.data;

          // 如果命令已完成或出错，显示详情
          if (result.status === 'completed' || result.status === 'failed' || result.status === 'timeout') {
            this.selectedCommand = result;
            this.dialogVisible = true;

            // 根据结果显示不同的消息
            if (result.success) {
              this.$message.success('命令执行成功');
            } else {
              this.$message.warning('命令执行失败: ' + (result.error_msg || '未知错误'));
            }
            return;
          }

          // 如果命令仍在执行，继续轮询
          setTimeout(() => {
            this.pollCommandResult(commandId, attempts + 1);
          }, 3000); // 每3秒查询一次
        } else {
          // 查询失败，但仍继续尝试
          setTimeout(() => {
            this.pollCommandResult(commandId, attempts + 1);
          }, 3000);
        }
      } catch (error) {
        console.error('获取命令结果失败:', error);
        // 出错后仍继续尝试
        setTimeout(() => {
          this.pollCommandResult(commandId, attempts + 1);
        }, 3000);
      }
    },
    resetCommand() {
      this.$refs.commandForm.resetFields();
    },
    // 命令历史相关方法
    async fetchCommandHistory() {
      this.historyLoading = true;
      try {
        const params = {
          page: this.currentPage,
          page_size: this.pageSize
        };

        // 添加 Agent ID 过滤
        if (this.historyFilter.agent_id) {
          params.agent_id = this.historyFilter.agent_id;
        }

        // 添加状态过滤
        if (this.historyFilter.status) {
          params.status = this.historyFilter.status;
        }

        // 添加搜索过滤
        if (this.historyFilter.search) {
          params.search = this.historyFilter.search;
        }

        // 添加日期范围过滤
        if (this.historyFilter.date_range && this.historyFilter.date_range.length === 2) {
          params.start_time = this.historyFilter.date_range[0] / 1000;
          params.end_time = this.historyFilter.date_range[1] / 1000;
        }
        console.log('获取命令历史参数:', params);
        const response = await agentApi.getCommandHistory(params);
        if (response && response.code === 200) {
          // 接口返回标准格式: {code: 200, data: [...命令列表], msg: "获取成功"}
          if (Array.isArray(response.data)) {
            // 直接使用返回的数组
            this.commandHistory = response.data;
            this.total = response.data.length;
          } else if (response.data && response.data.items && Array.isArray(response.data.items)) {
            // 分页格式: {items: [...], total: 数量}
            this.commandHistory = response.data.items;
            this.total = response.data.total || response.data.items.length;
          } else if (response.data && typeof response.data === 'object') {
            // 对象格式，转换为数组
            this.commandHistory = Object.values(response.data);
            this.total = this.commandHistory.length;
          } else {
            this.commandHistory = [];
            this.total = 0;
          }
          console.log('命令历史数据:', this.commandHistory);
        } else {
          this.$message.error(response.msg || '获取命令历史失败');
          this.commandHistory = [];
          this.total = 0;
        }
      } catch (error) {
        console.error('获取命令历史失败:', error);
        this.$message.error('获取命令历史失败：' + (error.message || '未知错误'));
        this.commandHistory = [];
        this.total = 0;
      } finally {
        this.historyLoading = false;
      }
    },
    handleSizeChange(val) {
      this.pageSize = val;
      this.fetchCommandHistory();
    },
    handleCurrentChange(val) {
      this.currentPage = val;
      this.fetchCommandHistory();
    },
    getStatusType(status) {
      const statusMap = {
        'pending': 'info',
        'running': 'warning',
        'completed': 'success',
        'failed': 'danger',
        'timeout': 'danger'
      };
      return statusMap[status] || 'info';
    },
    viewCommandDetail(command) {
      this.selectedCommand = command;
      this.dialogVisible = true;
    },
    formatTime(timestamp) {
      if (!timestamp) return 'N/A';
      return new Date(timestamp).toLocaleString();
    },
    onAgentFilterChange() {
      this.fetchCommandHistory();
    },
    onStatusFilterChange() {
      this.fetchCommandHistory();
    },
    onSearchChange() {
      this.fetchCommandHistory();
    },
    onDateRangeChange() {
      this.fetchCommandHistory();
    },
    refreshHistory() {
      this.fetchCommandHistory();
    },
    onBatchModeChange() {
      this.fetchAgentList();
    },
    showCommandTemplates() {
      this.templateDialogVisible = true;
    },
    async fetchTemplates() {
      try {
        const response = await agentApi.getTemplates();
        if (response && response.code === 200) {
          this.systemTemplates = response.data.system || [];
          this.fileTemplates = response.data.file || [];
          this.networkTemplates = response.data.network || [];
        }
      } catch (error) {
        this.$message.error('获取命令模板失败：' + error.message);
      }
    }
  }
};
